let casePanel='brief',caseMathFeedback={};
function caseRecord(){return state.casePlans[state.business]||(state.casePlans[state.business]={decisions:{},numeric:{},scenario:{},reflection:''});}
function caseStats(c){return{ctr:c.clicks/c.impressions*100,cpc:c.spend/c.clicks,reportedCPL:c.spend/c.reported,qualifiedCPL:c.spend/c.qualified,cac:c.spend/c.customers,qualifiedCVR:c.qualified/c.clicks*100,closeRate:c.customers/c.qualified*100,roas:c.revenue/c.spend,contribution:c.revenue*c.margin/100-c.spend,breakEvenCPL:c.revenue/c.customers*c.margin/100*c.customers/c.qualified};}
function caseQuestions(){const c=CAMPAIGN_CASES[state.business],s=caseStats(c);return[
 {id:'qualified',q:W('Qualified lead / valid order ka cost kitna Rs?','What is the cost per qualified lead / valid order (Rs)?'),answer:s.qualifiedCPL,working:`${c.spend.toLocaleString('en-PK')} ÷ ${c.qualified} = ${num(s.qualifiedCPL,2)}`},
 {id:'customer',q:W('Har paying customer ka acquisition cost kitna Rs?','What is acquisition cost per paying customer (Rs)?'),answer:s.cac,working:`${c.spend.toLocaleString('en-PK')} ÷ ${c.customers} = ${num(s.cac,2)}`},
 {id:'contribution',q:W('Ads ke baad contribution kitna Rs? Negative answer allowed hai.','What is contribution after ads (Rs)? Negative answers are allowed.'),answer:s.contribution,working:`${c.revenue.toLocaleString('en-PK')} × ${c.margin/100} − ${c.spend.toLocaleString('en-PK')} = ${num(s.contribution,2)}`}
 ];}
function caseCompletion(){const c=CAMPAIGN_CASES[state.business],r=caseRecord();return c.decisions.filter((d,i)=>r.decisions[i]===d[2]).length+caseQuestions().filter(q=>checkMath(q,r.numeric[q.id]||'').correct).length;}
function caseView(){const c=CAMPAIGN_CASES[state.business],r=caseRecord();return `<div class="case-banner"><div class="eyebrow">FICTIONAL WORKED CASE · ${esc(t(biz().name))}</div><h2>${U('Clicks se business result tak.','From clicks to business results.')}</h2><p>${U('Brief parho, numbers solve karo, evidence se decision lo, phir assumptions test karo.','Read the brief, solve the numbers, make evidence-based decisions, then test assumptions.')}</p><div class="badge-row"><span class="tag">${esc(t(c.period))}</span><span class="tag">${caseCompletion()}/6 ${U('checks solved','checks solved')}</span></div></div><div class="tabs case-tabs">${[['brief',W('1. Brief aur data','1. Brief & data')],['numbers',W('2. Hisaab khud karo','2. Calculate it')],['decisions',W('3. Decision lo','3. Make decisions')],['model',W('4. What-if model','4. What-if model')],['plan',W('5. Action plan','5. Action plan')]].map(([id,n])=>`<button class="${casePanel===id?'active':''}" data-case-panel="${id}">${t(n)}</button>`).join('')}</div>${({brief:caseBrief,numbers:caseNumbers,decisions:caseDecisions,model:caseModel,plan:casePlan}[casePanel])()}`;}
function caseBrief(){const c=CAMPAIGN_CASES[state.business];return `<div class="cards"><article class="card"><h3>${U('Business ki kahani','The business story')}</h3><p>${esc(t(c.story))}</p><div class="table-wrap"><table><tbody>${[['Impressions',c.impressions],['Clicks',c.clicks],['Ad spend',money(c.spend)],['Reported forms / conversions',c.reported],['Qualified leads / valid orders',c.qualified],['Paying customers',c.customers],['Period revenue',money(c.revenue)],['Contribution margin before ads',c.margin+'%']].map(([l,v])=>`<tr><td>${l}</td><td><b>${esc(typeof v==='number'?v.toLocaleString('en-PK'):v)}</b></td></tr>`).join('')}</tbody></table></div></article><aside class="card"><div class="eyebrow">EVIDENCE, NOT ASSUMPTIONS</div><h3>${U('Audit mein kya mila?','What did the audit find?')}</h3><ol class="steps">${c.evidence.map(e=>`<li>${esc(t(e))}</li>`).join('')}</ol><div class="note">${U('Saara data fictional teaching example hai. Market benchmark, real client result ya Google performance forecast nahi. Margin mein relevant variable costs included aur fixed overhead excluded hain.','All data is fictional teaching material, not market benchmarks, real client results or a Google performance forecast. Margin includes relevant variable costs and excludes fixed overhead.')}</div><button class="btn" data-case-panel="numbers" style="margin-top:20px">${U('Ab hisaab karo','Calculate the results')} →</button></aside></div>`;}
function caseNumbers(){const r=caseRecord();return `<div class="cards">${caseQuestions().map(q=>{const raw=r.numeric[q.id]||'',f=caseMathFeedback[state.business+'/'+q.id];return `<article class="card"><div class="eyebrow">USE THE CASE DATA</div><h3>${esc(t(q.q))}</h3><label class="field" style="margin-top:18px">${U('Tumhara answer (Rs)','Your answer (Rs)')}<input type="text" inputmode="decimal" data-case-number="${q.id}" value="${esc(raw)}" autocomplete="off"></label><button class="btn light" data-case-number-check="${q.id}">${U('Check karo','Check answer')}</button>${f?`<div class="feedback ${f.correct?'':'error'}" style="margin-top:15px" role="status">${f.correct?`✓ ${U('Sahi. Working:','Correct. Working:')}<div class="formula">${esc(q.working)}</div>`:!f.valid?U('Valid number dalo; commas aur negative sign allowed hain.','Enter a valid number; commas and negative signs are allowed.'):U('Denominator aur contribution margin dobara check karo.','Check the denominator and contribution margin again.')}</div>`:''}</article>`;}).join('')}<article class="card"><h3>${U('Data yaad nahi?','Need the data again?')}</h3><p>${U('Qualified leads, forms aur customers ko mix mat karo. Har metric ka denominator alag ho sakta hai.','Do not mix qualified leads, forms and customers. Each metric can have a different denominator.')}</p><button class="btn light" data-case-panel="brief">${U('Brief dekho','View the brief')}</button><button class="btn" data-case-panel="decisions" style="margin-top:12px">${U('Decisions par jao','Move to decisions')} →</button></article></div>`;}
function caseDecisions(){const c=CAMPAIGN_CASES[state.business],r=caseRecord();return `<div class="cards">${c.decisions.map((d,i)=>{const a=r.decisions[i],ok=a===d[2];return `<article class="card"><div class="eyebrow">DECISION ${i+1}</div><h3>${esc(t(d[0]))}</h3><div class="quiz-options">${d[1].map((o,j)=>`<button class="option ${a===j?(ok?'correct':'wrong'):''}" data-case-choice="${i}" data-choice="${j}">${esc(t(o))}</button>`).join('')}</div>${a!==undefined?`<div class="feedback ${ok?'':'error'}" role="status"><b>${ok?U('Evidence ke saath fit hota hai.','Fits the evidence.'):U('Evidence dobara dekho.','Review the evidence.')}</b> ${esc(t(d[3]))}</div>`:''}</article>`;}).join('')}<article class="card"><h3>${U('Result ko predict nahi, model karo','Model the result, do not promise it')}</h3><p>${U('Ab CPC, qualified conversion rate aur close rate badal kar dekho business economics par kya asar aata hai.','Change CPC, qualified conversion rate and close rate to explore business economics.')}</p><button class="btn" data-case-panel="model">${U('What-if model kholo','Open the what-if model')} →</button></article></div>`;}
function caseScenarioDefaults(){const c=CAMPAIGN_CASES[state.business],s=caseStats(c);return{budget:String(c.spend),cpc:String(s.cpc),cvr:String(+s.qualifiedCVR.toFixed(6)),close:String(+s.closeRate.toFixed(6))};}
function scenarioMetrics(values,c){const keys=['budget','cpc','cvr','close'];if(keys.some(k=>values[k]===undefined||String(values[k]).trim()===''||!Number.isFinite(Number(values[k]))))return null;const v=Object.fromEntries(keys.map(k=>[k,Number(values[k])]));if(v.budget<0||v.budget>1e9||v.cpc<=0||v.cvr<0||v.cvr>100||v.close<0||v.close>100)return null;const clicks=v.budget/v.cpc,leads=clicks*v.cvr/100,customers=leads*v.close/100,revenue=customers*(c.revenue/c.customers);return{clicks,leads,customers,revenue,contribution:revenue*c.margin/100-v.budget};}
function caseModel(){const c=CAMPAIGN_CASES[state.business],r=caseRecord(),v={...caseScenarioDefaults(),...r.scenario};return `<div class="cards"><section class="card"><div class="simulation-label">ASSUMPTION MODEL · NOT A GOOGLE FORECAST</div><h3 style="margin-top:15px">${U('Agar ye numbers change hon…','What if these numbers change…')}</h3><p>${U('Defaults case ke actual fictional numbers se calculated hain. Ye training model hai; Google auction behavior simulate nahi karta.','Defaults are calculated from the fictional case data. This training model does not simulate Google auction behavior.')}</p><div class="form-grid">${[['budget','Ad budget (Rs)'],['cpc','Average CPC (Rs)'],['cvr','Click → qualified lead/order (%)'],['close','Qualified lead/order → customer (%)']].map(([k,l])=>`<label class="field">${l}<input type="number" data-case-model="${k}" value="${esc(v[k])}" step="any" ${k==='budget'?'min="0" max="1000000000"':k==='cpc'?'min="0.01"':'min="0" max="100"'}></label>`).join('')}</div><div class="note">${U('Revenue per customer','Revenue per customer')}: ${money(c.revenue/c.customers)} · ${c.margin}% contribution margin. ${U('Fixed overhead aur future repeat revenue excluded.','Fixed overhead and future repeat revenue excluded.')}</div><button class="text-btn" id="case-reset-model" style="margin-top:20px">${U('Case defaults wapas lao','Restore case defaults')}</button></section><section class="card"><div class="eyebrow">MODELLED, NOT GUARANTEED</div><div id="case-model-results" aria-live="polite"></div></section></div>`;}
function updateCaseModel(){const c=CAMPAIGN_CASES[state.business],values=Object.fromEntries($$('[data-case-model]').map(i=>[i.dataset.caseModel,i.value]));caseRecord().scenario=values;save();const s=scenarioMetrics(values,c);$('#case-model-results').innerHTML=!s?`<div class="feedback error">${U('Valid numbers dalo: CPC zero se zyada aur rates 0–100%.','Enter valid numbers: CPC above zero and rates from 0–100%.')}</div>`:`<div class="metrics">${metric('Expected clicks',num(s.clicks),'Budget ÷ CPC')}${metric('Qualified leads / orders',num(s.leads),'Clicks × qualified CVR')}${metric('Expected customers',num(s.customers),'Qualified outcomes × close rate')}${metric('Expected revenue',money(s.revenue),'Customers × revenue/customer')}${metric('Contribution after ads',money(s.contribution),'Before fixed overhead')}${metric('Change vs case baseline',money(s.contribution-caseStats(c).contribution),'Model difference, not measured uplift')}</div><p style="font-size:12px">${U('Fractional customers expected averages hain. CPC, CVR aur close rate independent guaranteed levers nahi. Demand aur capacity se actual outcome change ho sakta hai.','Fractional customers are expected averages. CPC, CVR and close rate are not independent guaranteed levers. Demand and capacity can change actual outcomes.')}</p>`;}
function casePlan(){const c=CAMPAIGN_CASES[state.business],r=caseRecord();return `<div class="cards"><section class="card"><h3>${U('Apna action plan likho','Write your action plan')}</h3><p>${U('Evidence → bottleneck → ek focused action → success metric → next review. Real client ke sensitive details mat likho.','Evidence → bottleneck → one focused action → success metric → next review. Do not enter sensitive real-client information.')}</p><label class="field">${U('Mera plan','My plan')}<textarea id="case-reflection" maxlength="4000" placeholder="${U('Mujhe evidence mein ___ nazar aaya. Is liye pehla action ___ hoga.','The evidence shows ___. My first action will be ___.')}">${esc(r.reflection||'')}</textarea></label><p id="case-plan-status" style="font-size:11px;color:var(--muted)">${U('Typing par is browser mein save hoga.','Typing saves in this browser.')}</p><button class="btn" id="export-case">${U('Case aur mera plan export','Export case and my plan')}</button></section><aside class="card"><h3>${U('Tumhara evidence pack','Your evidence pack')}</h3><div class="coverage-item"><b>Calculation + decision checks</b><span>${caseCompletion()}/6</span></div><p>${U('Case solve karna real account mastery ka certificate nahi. Export mein fictional baseline, tumharay answers aur assumptions labelled honge.','Solving the case does not certify live account mastery. The export labels the fictional baseline, your answers and assumptions.')}</p><div class="action-row"><button class="btn light" data-case-help="tracking">${U('Tracking practice','Tracking practice')}</button><button class="btn light" data-go="guides">${U('Implementation workbook','Implementation workbook')}</button></div></aside></div>`;}
function bindCase(){$$('[data-case-panel]').forEach(b=>b.onclick=()=>{casePanel=b.dataset.casePanel;render();});$$('[data-case-choice]').forEach(b=>b.onclick=()=>{caseRecord().decisions[b.dataset.caseChoice]=+b.dataset.choice;save();const y=window.scrollY;render();window.scrollTo(0,y);});$$('[data-case-number-check]').forEach(b=>b.onclick=()=>{const id=b.dataset.caseNumberCheck,q=caseQuestions().find(q=>q.id===id),raw=document.querySelector(`[data-case-number="${id}"]`).value;caseRecord().numeric[id]=raw;caseMathFeedback[state.business+'/'+id]=checkMath(q,raw);save();const y=window.scrollY;render();window.scrollTo(0,y);});if(casePanel==='model'){$$('[data-case-model]').forEach(i=>i.oninput=updateCaseModel);updateCaseModel();$('#case-reset-model').onclick=()=>{caseRecord().scenario={};save();render();};}const reflection=$('#case-reflection');if(casePanel==='plan'){reflection.oninput=()=>{caseRecord().reflection=reflection.value;save();$('#case-plan-status').textContent=storageOK?U('Plan save ho gaya.','Plan saved.'):U('Storage unavailable — export se backup lo.','Storage unavailable — export a backup.');};$('#export-case').onclick=()=>download('ads-asaan-'+state.business+'-worked-case.json',{fictionalCase:true,notPerformanceForecast:true,business:biz().name[1],baseline:CAMPAIGN_CASES[state.business],baselineMetrics:caseStats(CAMPAIGN_CASES[state.business]),learnerPlan:caseRecord(),checksSolved:caseCompletion(),exportedAt:new Date().toISOString()});}$$('[data-case-help]').forEach(b=>b.onclick=()=>{workshopTab='tracking';go('workshop');render();});bindNavigation();}
function cleanCasePlans(v){const result={};if(!v||typeof v!=='object')return result;for(const b of BUSINESSES){const x=v[b.id],c=CAMPAIGN_CASES[b.id];if(!x||typeof x!=='object')continue;const r={decisions:{},numeric:{},scenario:{},reflection:typeof x.reflection==='string'?x.reflection.slice(0,4000):''};for(let i=0;i<c.decisions.length;i++)if(Number.isInteger(x.decisions?.[i])&&x.decisions[i]>=0&&x.decisions[i]<c.decisions[i][1].length)r.decisions[i]=x.decisions[i];for(const k of ['qualified','customer','contribution'])if(typeof x.numeric?.[k]==='string')r.numeric[k]=x.numeric[k].slice(0,50);for(const k of ['budget','cpc','cvr','close'])if(['string','number'].includes(typeof x.scenario?.[k]))r.scenario[k]=String(x.scenario[k]).slice(0,30);result[b.id]=r;}return result;}
function caseSolvedForBusiness(id){const c=CAMPAIGN_CASES[id],s=caseStats(c),r=state.casePlans[id]||{};return c.decisions.filter((d,i)=>r.decisions?.[i]===d[2]).length+Object.entries({qualified:s.qualifiedCPL,customer:s.cac,contribution:s.contribution}).filter(([key,answer])=>checkMath({answer},r.numeric?.[key]||'').correct).length;}
function casePage(){return `${heading('A COMPLETE WORKED CAMPAIGN',U('Numbers ko decision mein badlo.','Turn numbers into decisions.'),U('Teen fictional businesses. Har case mein brief, calculation, strategy aur action plan.','Three fictional businesses. Each case connects a brief, calculations, strategy and an action plan.'))}<div class="section-heading"><span class="tag">${esc(t(biz().name))}</span><select id="case-business" class="lang" aria-label="Case business">${BUSINESSES.map(b=>`<option value="${b.id}" ${b.id===state.business?'selected':''}>${esc(t(b.name))}</option>`).join('')}</select></div>${caseView()}${footer()}`;}
function bindStandaloneCase(){$('#case-business').onchange=e=>{state.business=e.target.value;save();render();};bindCase();}
